<section class="card"><h2>Project settings</h2><?php $projectEditing=$project;$projectFormAction=$workPath.'/save';require __DIR__.'/project-form.php'; ?></section>
<section class="card"><div class="section-heading"><div><h2>Workflow states</h2><p class="muted">Groups power completion reports; names and colours are yours.</p></div></div><?php foreach($states as $state): ?><details class="work-setting-row"><summary><span class="work-state-dot" data-work-color="<?= e($state['color']) ?>"></span><strong><?= e($state['name']) ?></strong><span class="badge"><?= e(WorkService::GROUPS[$state['state_group']]) ?></span></summary><form class="form-grid" method="post" action="<?= $workPath ?>/state"><?= csrf_field() ?><input type="hidden" name="item_id" value="<?= e($state['id']) ?>"><label>Name<input name="name" value="<?= e($state['name']) ?>" maxlength="80" required></label><label>Group<select name="state_group"><?php foreach(WorkService::GROUPS as $value=>$label): ?><option value="<?= $value ?>" <?= $state['state_group']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach; ?></select></label><label>Colour<input type="color" name="color" value="<?= e($state['color']) ?>"></label><label>Order<input name="position" type="number" min="0" max="1000" value="<?= e($state['position']) ?>"></label><label>WIP limit<input name="wip_limit" type="number" min="1" max="1000" value="<?= e($state['wip_limit']??'') ?>" placeholder="No limit"><small>Warn when this state exceeds the active-item limit.</small></label><div class="full"><button class="secondary">Save state</button></div></form><?php if(count($states)>1): ?><form class="work-inline-form" method="post" action="<?= $workPath ?>/state/<?= e($state['id']) ?>/remove" data-confirm="Remove this state and move all of its work items to the selected replacement?"><?= csrf_field() ?><label>Replacement state<select name="replacement"><?php foreach($states as $replacement):if($replacement['id']===$state['id'])continue; ?><option value="<?= e($replacement['id']) ?>"><?= e($replacement['name']) ?></option><?php endforeach; ?></select></label><button class="quiet">Remove state</button></form><?php endif; ?></details><?php endforeach; ?><details><summary>+ New workflow state</summary><form class="form-grid" method="post" action="<?= $workPath ?>/state"><?= csrf_field() ?><label>Name<input name="name" maxlength="80" required></label><label>Group<select name="state_group"><?php foreach(WorkService::GROUPS as $value=>$label): ?><option value="<?= $value ?>"><?= $label ?></option><?php endforeach; ?></select></label><label>Colour<input type="color" name="color" value="#3688ff"></label><label>Order<input name="position" type="number" min="0" max="1000" value="<?= count($states) ?>"></label><label>WIP limit<input name="wip_limit" type="number" min="1" max="1000" placeholder="No limit"></label><div class="full"><button>Create state</button></div></form></details></section>
<section class="card"><h2>Labels</h2><?php foreach($labels as $label): ?><details class="work-setting-row"><summary><span class="work-state-dot" data-work-color="<?= e($label['color']) ?>"></span><strong><?= e($label['name']) ?></strong></summary><form class="form-grid" method="post" action="<?= $workPath ?>/label"><?= csrf_field() ?><input type="hidden" name="item_id" value="<?= e($label['id']) ?>"><label>Name<input name="name" value="<?= e($label['name']) ?>" maxlength="80" required></label><label>Colour<input name="color" type="color" value="<?= e($label['color']) ?>"></label><div class="full"><button class="secondary">Save label</button></div></form><form method="post" action="<?= $workPath ?>/label/<?= e($label['id']) ?>/remove" data-confirm="Remove this label from the project? Work items will be kept."><?= csrf_field() ?><button class="quiet">Remove label</button></form></details><?php endforeach; ?><form class="form-grid" method="post" action="<?= $workPath ?>/label"><?= csrf_field() ?><label>New label<input name="name" maxlength="80" required placeholder="Bug, Design, Research..."></label><label>Colour<input name="color" type="color" value="#9f8bff"></label><div class="full"><button>Add label</button></div></form></section>
<section class="card"><h2>Export &amp; archive</h2><p class="muted">Export your project data or archive it without deleting its work items, pages and history.</p><div class="hero-actions"><a class="btn secondary" href="<?= $workPath ?>/export" hx-boost="false">Export project JSON</a><a class="btn secondary" href="<?= $workPath ?>/export.csv" hx-boost="false">Export active work items CSV</a><?php if($project['status']!=='archived'): ?><form method="post" action="<?= $workPath ?>/archive" data-confirm="Archive this project? Its content is preserved and can be restored."><?= csrf_field() ?><button class="secondary">Archive project</button></form><?php endif; ?></div><p class="footnote">Project JSON contains structured data. Use LifeOS encrypted backups to include attachment files and all workspaces.</p></section>
